import{_ as i,o as t,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"2～18k的前端面试会问个啥","description":"？ 这是我参与更文挑战的第16天，活动详情查看：更文挑战 长文警告 写了那么久的技术文，来点不一样的吧。 最近公司招人，所以面试了一波，总结了一下前端这个区间内的要求吧。 仅代表个人意见和理解 名词解释 程度副词 对于不同程度的词，我的理解如下： 精通 了解背后的原理和规范 动手。","frontmatter":{"title":"2～18k的前端面试会问个啥","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","实战与性能"],"description":"？ 这是我参与更文挑战的第16天，活动详情查看：更文挑战 长文警告 写了那么久的技术文，来点不一样的吧。 最近公司招人，所以面试了一波，总结了一下前端这个区间内的要求吧。 仅代表个人意见和理解 名词解释 程度副词 对于不同程度的词，我的理解如下： 精通 了解背后的原理和规范 动手。","sidebarWeight":2,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/常用技巧/2～18k的前端面试会问个啥.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/08-实战与性能/2～18k的前端面试会问个啥.md","filePath":"posts/JavaScript系统教程/08-实战与性能/2～18k的前端面试会问个啥.md"}'),r={name:"posts/JavaScript系统教程/08-实战与性能/2～18k的前端面试会问个啥.md"};function n(e,l,p,g,a,u){return t(),o("div",null,[...l[0]||(l[0]=[s('<div><h1 id="_2-18k的前端面试会问个啥" tabindex="-1">2～18k的前端面试会问个啥 <a class="header-anchor" href="#_2-18k的前端面试会问个啥" aria-label="Permalink to &quot;2～18k的前端面试会问个啥&quot;">​</a></h1><blockquote><p>本节目标：理解“2～18k的前端面试会问个啥”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <strong>？</strong> 这是我参与更文挑战的第16天，活动详情查看：<a href="https://juejin.cn/post/6967194882926444557" target="_blank" rel="noreferrer">更文挑战</a> 长文警告 写了那么久的技术文，来点不一样的吧。 最近公司招人，所以面试了一波，总结了一下前端这个区间内的要求吧。 仅代表个人意见和理解 <strong>名词解释</strong><strong>程度副词</strong> 对于不同程度的词，我的理解如下： <strong>精通</strong></p></blockquote><ul><li>了解背后的原理和规范</li><li>动手重写过实现代码</li><li>可以以为此为基础做二次开发</li><li>能读懂源码并做出修改</li></ul><p><strong>掌握</strong></p><ul><li>曾在项目中大量使用过此技术</li><li>可以自如的使用这项技术进行开发</li><li>参与技术论坛区讨论或者写过相关文章</li></ul><p><strong>熟悉</strong></p><ul><li>曾在项目中使用过</li><li>通读过相关文档</li><li>可以快速对相关问题定位到文档内容中</li><li>了解一些较冷僻的相关语法糖和api等</li></ul><p><strong>了解</strong></p><ul><li>未在开发中使用过，但写过demo</li><li>阅读过相关文档或者视频教程</li><li>可以用五分钟内向他人介绍这项技术的特点和应用场景</li></ul><p><strong>不了解</strong></p><ul><li>只是听过名字</li><li>只是大概的翻过文档</li><li>没有写过关于这项技术的代码</li><li>需要同时具备当前等级所有特性</li><li>高等级描述包含低等级描述特性</li></ul><p>非常多的简历中写到的了解，其实是不了解，熟悉和掌握可能往往只是了解的水平，如果你写的精通，那么我就要带着电脑来面试你了。</p><p><strong>手写代码：</strong> 可以借助emmet或者编辑器的提醒，非复制粘贴整段代码的方式书写代码。 <strong>记忆性考察：</strong> 需要背下来的内容，不可以借助搜索引擎。比如大多数关键字的拼写，对于超长关键词可以借助编辑器完成输入。 一些常用的知识点也会要求记忆性考察，比如盒模型和选择器规则，因为日常使用频度较高，理应记住。 <strong>索引性考察：</strong> 可以一次性在搜索引擎通过技术关键字找到解决方案。比如： 我们希望做一个特殊效果的轮播图，文字和背景图不同步滚动，背景图每次只是水平偏移一小截，文字则是整页的滚动 面对这个描述能够识别出搜索关键词为“视差滚动” <strong>理解性考察：</strong> 要求能够通过代码的方式展现知识点以及和其他知识点的对比。 能够在某应用场景内设计出该技术的使用方案。 能够讲清其背后的数学原理或者逻辑关系。</p><p><strong>面试意图</strong><strong>正面</strong></p><ol><li>是否具有工作岗位所需要的最低能力</li><li>是否有过类似项目开发经历</li><li>是否掌握工作岗位所需技能</li><li>现场编码解决问题</li><li>正确使用搜索引擎</li><li>能够对之前项目中使用过的技术做出详细解释</li><li>是否对技术有热情</li><li>有在线可访问的代码</li><li>有技术博客</li><li>在技术社区积极回答问题</li><li>关注新技术，并且做过官方demo以外的案例</li><li>日常使用技术解决生活中的问题</li><li>成长空间</li><li>计算机专业背景</li><li>良好的算法基础</li><li>良好的表达能力</li><li>做过技术文章翻译</li><li>有至少一项5年以上的爱好</li></ol><p><strong>反面</strong></p><ol><li>对冷门知识点做记忆性考察</li><li>对过时知识点做解释型</li><li>以回答出问题的个数作为录用指标</li><li>面试应该像测视力一样，一开始从最容易的问题入手，逐步深入，直到无法正确回答。</li><li>如果面试中面试者没有回答对任何问题或者回答对了所有的问题，都不是一次成功的面试。</li></ol><p><strong>面试方式</strong></p><ul><li>了解职业经历，确认工作内容。</li><li>通过场景概括出技术能力范围。</li><li>面试前确认，模糊的地方在开始的时候确认。</li><li>参与了哪些项目，在项目中扮演什么角色，完成了哪些编码工作。</li><li>工作的流程是怎么样的，是否有规范（比如gitflow）工作的经验。</li><li>按照简历的技能列表挑选比较鲜明的做提问。</li><li>对于基础知识，比如HTTP协议，以记忆性考察为主；对于正则路由promise等技术如果不是近期项目使用过，但是- 声称掌握，可放宽为索引性考察。</li><li>我常常会进行一个额外的环节，就是让面试人在简历中圈出真实技能，排除注水内容，然后只对圈出内容进行提问。因为在我看来，环境所迫带来的简历注水也不该等同为面试人的品质问题，另一方面，是否能够正确评价自己是程序员的一项重要能力。</li></ul><p>我们公司使用的技术栈相关api问答，以及根据情况来询问更深层次的语法和用法等 大约5~10个问题，主要引导面试者讲述技术的原理，以及技术的使用形式，以及使用过程中遇到的问题（参看附录）。 比如面试者声称熟悉AJAX，我可能会问他AJAX使用了js的什么对象（原理），什么是异步函数（使用形式），跨域问题有没有遇到过（问题），JSONP为什么能解决跨域问题（原理），jsonp返回的内容和json有什么不同（使用），jsonp使用遇到过哪些局限性（问题）… 按照这个层次递进深入，直到面试者回答吃力或者无法回答。 一般不打断面试者的叙述，哪怕说的是错误的，也会在整段讲完之后再进行纠正，然后开始下一个话题。 做实际编码的测试，主要考察编程能力。 选用基本的js题目做测试，比如 在聚会中常玩数七的游戏，七的倍数和带有七的数字都不能说，比如14,27,28。请找出1~100的不能说的数字。</p><p><strong>考察的点有：</strong></p><ul><li>技术栈是否契合</li><li>技术深度</li><li>技术的基础了解程度</li><li>遇到问题的解题思路</li></ul><p><strong>总结</strong> 内容部分知识举例说明了一些常见的技能列表，实际上会根据面试者的简历情况设置问题。 记忆性内容作为底线要求，如果不能达标，意味着基础不牢，在日后的工作中会在很多基本的问题上搞不清。 编码环节主要做搜索性考察，因为这是工作的常态形式。使用搜索引擎的能力决定了程序员的日常水平。 理解性考察对应的是知识点的理解和应用，是否能够把知识点运用到开发中，并且对日常开发中遇到的问题有自己的思考，反应的是面试者的潜力和发展。 <strong>基本功考察</strong></p><ol><li>关于Html</li><li>html语义化标签的理解; 结构化的理解; 能否写出简洁的html结构; SEO优化</li><li>h5中新增的属性; 如自定义属性data, 类名className等, 新增表单元素, 拖拽Drag</li><li>h5中新增的API, 修改的API, 废弃的API 稍作了解 (离线存储, audio, video)</li><li>关于CSS</li><li>CSS选择器( 三大特性 )</li><li>BFC机制</li><li>盒模型</li><li>CSS模块化开发(封装); SCSS和LESS的使用</li><li>屏幕适配 以及 页面自适应</li><li>CSS3中新增的选择器</li><li>CSS3中新增的属性, transform trasition animation等…</li><li>关于布局</li><li>标准文档流(padding + margin + 负margin) + 浮动float + 定位</li><li>百分比布局(流式布局): px单位 用 %num代替, 占父级元素的百分比</li><li>flex弹性布局: 主轴 辅助轴的几个属性</li><li>grid栅格布局: 使用框架中的类名来替代: 本质上还是百分比布局</li><li>关于JS基础</li><li>变量数据类型及检测: 基本 + 引用</li><li>运算符: 算术 + 条件 + 逻辑 + 位 + 短路, 隐式转换等</li><li>条件, 循环, 异常处理 if switch(){case xxx:} try catch finally throw</li><li>函数定义, 调用方式(apply, call, 直接调用), 传参: 实参给形参赋值</li><li>字符串, 数组, 对象常用API,</li><li>正则表达式</li><li>关于JS高级</li><li>作用域, 作用域链, 闭包</li><li>原型, 原型链, 继承</li><li>函数上下文, this指向</li><li>js的运行机制, 事件队列和循环</li><li>同步, 异步编程</li><li>关于网络协议</li><li>HTTP协议</li><li>cookie, session, token</li><li>关于ES6语法</li><li>字符串, 数组, 对象 扩展的api</li><li>变量扩展: let const 解构赋值 块级作用域</li><li>函数扩展: 箭头函数 默认参数, rest参数</li><li>展开运算符, 模板字符串</li><li>set 和 map数据结构</li><li>迭代器和生成器函数 next 和 yield的理解</li><li>proxy对象 属性代理器: 属性的读取（get）和设置（set）相关操作</li><li>promise对象, 异步编程的解决方案</li><li>async + await: 异步编程的终极方案 promise + generator的语法糖</li><li>class语法 构造函数的语法糖</li><li>模块化编程 export + import 的 导出和导入</li><li>VUE基础</li><li>基本指令</li><li>实例的属性和方法</li><li>实例的生命周期</li><li>组件基础: 创建,注册,添加属性方法,套用等…</li><li>组件通信传值 父子, 兄弟, 跨级</li><li>插槽slot等…</li><li>VUE高级</li><li>vue-router: 搭建SPA</li><li>路由,组件的配置</li><li>路由间的传值</li><li>路由跳转</li><li>路由的导航守卫</li><li>记住在router.js 和 组件页面中的使用方式</li><li>vuex: 状态管理: 数据仓库store</li><li>实例化仓库的5大属性的使用</li></ol><p>state, getters, mutations, actions, modules</p><ul><li>辅助函数mapState等…, 仓库中计算属性的映射, 方便操作</li><li>记住在 store.js 和 组件中 使用方式</li><li>VUE深入, 源码阅读</li><li>数据响应式原理</li><li>virtual dom</li><li>diff 算法</li><li>nextTick等等…</li><li>vue2和vue3的数据绑定</li><li>vue3的componest API</li><li>vite的用法</li></ul><p><strong>DOM</strong><strong>掌握原生的DOM操作</strong><strong>增删查改</strong><strong>熟悉node和element对象</strong><strong>事件关于事件的机制</strong></p><ul><li>冒泡和捕获</li><li>事件委托</li><li>自定义事件</li><li>Event对象</li><li>面向对象</li></ul><p><strong>了解面向对象的思想，能够以面向对象的思想构建应用。比如封装一个日历组件，设计对象所需的属性值和方法。</strong></p><ul><li>new方法</li><li>继承，派生</li><li>原型和原型链</li></ul><p><strong>函数</strong></p><ul><li>熟悉Array，String等的方法</li><li>call和apply方法的使用</li><li>链式调用</li><li>this</li></ul><p><strong>工程化</strong></p><ol><li>掌握gulp</li><li>索引行考察手写gulp任务</li><li>掌握模块化</li><li>CMD标准</li><li>commonjs</li><li>ES6模块</li><li>babel如何使用</li><li>webpack打包方案</li><li>异步加载</li><li>打包多个文件</li><li>掌握webpack</li><li>阅读webpack文档</li><li>理解配置文件结构</li><li>合并，注入生效代码部分</li><li>热更新</li><li>CSS</li></ol><p><strong>命名策略</strong><strong>嵌套</strong><strong>变量</strong><strong>函数</strong><strong>了解nodeJS对于前端岗位，nodejs的使用主要集中在自动化和搭建简单的数据服务器两个方面。</strong></p><ul><li>是否上传过npm包</li><li>断点调试法</li><li>express</li><li>插件</li><li>中间件</li><li>路由原理</li><li>HTTP协议</li><li>数据库查询</li><li>HTML模板（ejs，pug）</li></ul><p><strong>了解ES6</strong></p><ul><li>promise</li><li>Generator</li><li>花括号作用域</li><li>class</li><li>数组遍历（ES5）</li><li>严格模式（ES5）</li><li>模块系统</li></ul><p><strong>框架专题</strong><strong>通用</strong></p><ul><li>MVC</li><li>双向数据绑定</li><li>单项数据流</li><li>组件化</li><li>生命期</li><li>路由</li></ul><p><strong>前端模板</strong></p><ul><li>横向对比，所用模板的优点</li><li>至少使用过两种以上的前端模板</li></ul><p><strong>工程能力考察:</strong></p><ol><li>项目能力</li><li>vue-cli脚手架搭建和功能配置 vue.config.js</li><li>vite的使用和搭建等</li><li>webpack的常用配置</li><li>项目构建 打包</li><li>熟悉各类框架的文档…</li><li>UI框架: Bootstrap, MUI, Element-ui等</li><li>常用的插件整理, 整理一个自己插件库, 封装自己的方法库,组件库</li><li>常用的工具熟练度</li><li>PC端和移动端开发注意事项和兼容性</li><li>经验总结: 如何快速确定项目的技术选型</li><li>坑点总结</li><li>项目遇到坑坑坑!!!</li><li>如何处理，如何提出issue并且合作处理</li><li>git或者svn等使用情况</li><li>项目中的性能优化记录 ( 都是细节点…多记录 )</li><li>需求文档的理解, 可以结合 项目流程图, UML图</li><li>问题解决能力: (bug定位调试, 查找文档, 寻求他人…)</li><li>平常有记录的习惯吗。</li></ol><p><strong>模块化, 组件化开发能力</strong></p><ul><li>项目分类; 各类文件整理,分类</li><li>各类功能封装</li><li>组件和功能模块的抽离, 解耦, 复用</li></ul><p><strong>内功考察:</strong></p><ol><li>面向对象的编程思想</li><li>类的抽象</li><li>对象的封装, 继承</li><li>为了更好的去管理数据, 分类数据 实现高内聚, 低</li><li>设计模式</li><li>设计模式感觉也是</li><li>将面向对象思想 再度抽象成现实中 某些特定模式</li><li>数据结构和算法</li><li>学习常用的排序搜索算法, 顺序表,链表,栈,队列,树,堆 结构等等…</li><li>考验你的 抽象思维 和 数学功底了</li><li>将现实需求 抽象成 计算机代码 的思维能力</li></ol><p><strong>附加技能考察:</strong></p><ol><li>学习能力</li><li>持续学习的态度–博客, 笔记记录</li><li>技术论坛活跃度高, 问答多</li><li>GitHub开源项目参与</li><li>了解一门后端语言</li><li>node.js, python, php等…</li><li>数据库mysql,redis,mongodb. sql的操作语句, mongo的操作语句, redis操作语句</li><li>node + express 搭建本地服务等</li><li>python + django + request + scrapy</li><li>系统编程</li><li>Linux命令行操作, 系统文件管理</li><li>多任务, 多线程, 多进程, 协程, 并发, 并行, 串行, 同步, 异步等概念的理解 &gt; 来自 &lt;<a href="https://juejin.cn/post/6977919113733603342" target="_blank" rel="noreferrer">https://juejin.cn/post/6977919113733603342</a>&gt;</li></ol></div>',1)])])}const m=i(r,[["render",n]]);export{d as __pageData,m as default};
